#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define PIN_PLUS  D1
#define PIN_MINUS D2
#define PIN_START D3
#define PIN_BUZZ  D10

#define SCREEN_W 128
#define SCREEN_H 64
Adafruit_SSD1306 display(SCREEN_W, SCREEN_H, &Wire, -1);

long setSeconds = 0;
long remainMs = 0;
bool running = false;
bool ringing = false;
unsigned long ringStart = 0;
unsigned long lastTick = 0;

struct Btn { int pin; bool last; unsigned long downT; unsigned long lastRep; };
Btn bPlus{PIN_PLUS,false,0,0}, bMinus{PIN_MINUS,false,0,0}, bStart{PIN_START,false,0,0};

bool pressedEdge(Btn &b) {
  bool now = (digitalRead(b.pin) == LOW);
  bool edge = (now && !b.last);
  if (edge) { b.downT = millis(); b.lastRep = millis(); }
  b.last = now;
  return edge;
}
bool heldRepeat(Btn &b, unsigned long interval) {
  bool now = (digitalRead(b.pin) == LOW);
  if (now && millis() - b.downT > 500 && millis() - b.lastRep > interval) {
    b.lastRep = millis();
    return true;
  }
  return false;
}

void showDisplay() {
  long s = running ? (remainMs + 999) / 1000 : setSeconds;
  if (s < 0) s = 0;
  char buf[6];
  snprintf(buf, sizeof(buf), "%02ld:%02ld", s / 60, s % 60);
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(3);
  display.setCursor(20, 12);
  display.print(buf);
  display.setTextSize(1);
  display.setCursor(8, 52);
  if (ringing) display.print("STOP: knopka");
  else if (running) display.print("START: pauza");
  else display.print("+/- minut START pusk");
  display.display();
}
void stopRing() { ringing = false; digitalWrite(PIN_BUZZ, LOW); }

void setup() {
  pinMode(PIN_PLUS, INPUT_PULLUP);
  pinMode(PIN_MINUS, INPUT_PULLUP);
  pinMode(PIN_START, INPUT_PULLUP);
  pinMode(PIN_BUZZ, OUTPUT);
  digitalWrite(PIN_BUZZ, LOW);
  Wire.begin();
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.setRotation(0);
  showDisplay();
}

void loop() {
  bool ePlus = pressedEdge(bPlus);
  bool eMinus = pressedEdge(bMinus);
  bool eStart = pressedEdge(bStart);
  bool repPlus = heldRepeat(bPlus, 120);
  bool repMinus = heldRepeat(bMinus, 120);
  if (ringing) {
    digitalWrite(PIN_BUZZ, ((millis() / 400) % 2 == 0) ? HIGH : LOW);
    if (ePlus || eMinus || eStart) stopRing();
    if (millis() - ringStart > 60000) stopRing();
    showDisplay(); delay(20); return;
  }
  if (!running) {
    if (ePlus || repPlus) { setSeconds += 60; if (setSeconds > 99*60+59) setSeconds = 99*60+59; showDisplay(); }
    if (eMinus || repMinus) { setSeconds -= 60; if (setSeconds < 0) setSeconds = 10*60; showDisplay(); }
    if (eStart) {
      if (setSeconds <= 0) setSeconds = 60;
      running = true; remainMs = setSeconds * 1000L; lastTick = millis(); showDisplay();
    }
    if ((digitalRead(PIN_START) == LOW) && (millis() - bStart.downT > 1200) && setSeconds > 0) {
      setSeconds = 0; running = false; showDisplay(); delay(300); bStart.downT = millis();
    }
  } else {
    unsigned long now = millis();
    remainMs -= (long)(now - lastTick);
    lastTick = now;
    if (remainMs <= 0) { remainMs = 0; running = false; setSeconds = 0; ringing = true; ringStart = millis(); }
    if (eStart) { running = false; setSeconds = (remainMs + 999) / 1000; digitalWrite(PIN_BUZZ, LOW); }
    if (ePlus) remainMs += 60000;
    if (eMinus) { remainMs -= 60000; if (remainMs < 0) remainMs = 0; }
    showDisplay();
  }
  delay(20);
}

